{
  "avaliacoes": [
    {
      "id": "E339a40579aa65b7e",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte indica que os tanques de carga devem dispor de procedimentos de teste das válvulas de pressão e vácuo e de meios para assegurar a ventilação caso a válvula principal falhe.",
          "trechos": [
            "E339a40579aa65b7e:0:700"
          ],
          "condicoes": [
            "aplica-se ao contexto de ventilação e proteção contra sobrepressão/vácuo de tanques de carga em FPSO/FSU descrito pela fonte",
            "pressupõe operação com conjuntos integrados automáticos de válvulas de pressão e vácuo"
          ],
          "limites": [
            "documento de jurisdição estrangeira",
            "o trecho não define periodicidades detalhadas de teste nem arranjos completos de redundância"
          ]
        },
        {
          "proposicao": "A fonte recomenda instalar um emergency pressure/vacuum breaker para falha da válvula principal e tratá-lo como elemento crítico de segurança sujeito a testes e manutenção rotineiros.",
          "trechos": [
            "E339a40579aa65b7e:0:700"
          ],
          "condicoes": [
            "aplica-se ao cenário em que a válvula principal de pressão/vácuo falha ou não alivia na taxa apropriada",
            "refere-se ao sistema de proteção de tanques de carga"
          ],
          "limites": [
            "a recomendação é apresentada no contexto da fonte e não como requisito brasileiro",
            "o trecho não informa critérios de aceitação de desempenho além do dimensionamento para o maior cenário de sobrepressão possível"
          ]
        },
        {
          "proposicao": "Quando houver sistema de blanketing/recuperação de hidrocarbonetos, a fonte recomenda procedimentos para manter disponível o sistema de gás inerte, medidas secundárias em caso de falha de comutação e método fail-safe para garantir rota ao flare e evitar sobrepressão.",
          "trechos": [
            "E339a40579aa65b7e:700:1391",
            "E339a40579aa65b7e:1391:2087"
          ],
          "condicoes": [
            "aplica-se a FPSOs com sistema de blanketing/recuperação de hidrocarbonetos nos tanques",
            "considera o risco de indisponibilidade do sistema de blanketing e fechamento potencial da rota ao flare"
          ],
          "limites": [
            "o trecho não apresenta arquitetura detalhada do fail-safe nem lógica completa de intertravamento",
            "o documento remete a normas e guias estrangeiros, sem convertê-los em requisito brasileiro"
          ]
        }
      ]
    },
    {
      "id": "E28a0d8db9652cff9",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Para inspecionar tanques de carga após operação com hidrocarbonetos, a fonte informa que será necessário gas freeing e, para viabilizá-lo, um gerador de gás inerte.",
          "trechos": [
            "E28a0d8db9652cff9:0:698"
          ],
          "condicoes": [
            "aplica-se ao contexto de tanques de carga em FPSO durante preparação para inspeção",
            "pressupõe que os tanques tenham sido mantidos com atmosfera contendo vapores de hidrocarbonetos"
          ],
          "limites": [
            "o trecho não detalha o procedimento completo de retirada de serviço e retorno à operação",
            "não define alternativas equivalentes ao gerador de gás inerte"
          ]
        },
        {
          "proposicao": "A fonte explica que o gás inerte é usado para deslocar vapores de hidrocarbonetos do tanque mantendo o teor de oxigênio abaixo do limite explosivo dos hidrocarbonetos antes da purga com ar.",
          "trechos": [
            "E28a0d8db9652cff9:698:1391"
          ],
          "condicoes": [
            "aplica-se à preparação de tanques para gas freeing e entrada",
            "refere-se a tanques contendo vapores de hidrocarbonetos"
          ],
          "limites": [
            "a redação da fonte mistura descrição operacional e critério de segurança, sem desenvolver todos os mecanismos de combustão",
            "o trecho não fornece parâmetros completos para todas as composições possíveis de atmosfera"
          ]
        },
        {
          "proposicao": "Durante a lavagem de tanque usado para transporte de óleo cru, a fonte determina interrupção do processo se o teor de oxigênio exceder 8%, retomando apenas quando as condições estiverem estáveis em 8% ou menos; depois, a atmosfera deve ser purgada com gás inerte até poder ser testada e demonstrada adequada.",
          "trechos": [
            "E28a0d8db9652cff9:1391:2053"
          ],
          "condicoes": [
            "aplica-se a tanque que tenha sido usado para óleo cru",
            "refere-se à etapa de tank washing anterior à entrada"
          ],
          "limites": [
            "documento de jurisdição estrangeira",
            "o trecho não expõe os critérios finais de liberação para entrada além da necessidade de teste e demonstração de segurança"
          ]
        }
      ]
    },
    {
      "id": "E1d2dee61969ee6ad",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte descreve que o computador de estabilidade registra conteúdos dos tanques do casco, como lastro, óleo cru, óleo combustível e água doce, e os transfere ao programa de estabilidade, enquanto algumas variações de cargas de convés precisam de entrada manual pelo pessoal de marinha.",
          "trechos": [
            "E1d2dee61969ee6ad:0:697"
          ],
          "condicoes": [
            "aplica-se ao controle de estabilidade de instalação flutuante sob supervisão operacional",
            "pressupõe existência de load or stability computer integrado aos conteúdos de tanques"
          ],
          "limites": [
            "o trecho é descritivo e não apresenta requisitos mínimos de instrumentação, redundância ou validação de dados",
            "não informa como tratar erros de entrada manual"
          ]
        },
        {
          "proposicao": "Segundo a fonte, a maioria dos compartimentos é projetada para ser estanque, e danos ou alagamento em um compartimento devem permanecer contidos, sem migração de fluidos para compartimentos adjacentes.",
          "trechos": [
            "E1d2dee61969ee6ad:697:1394"
          ],
          "condicoes": [
            "aplica-se à integridade estanque de compartimentos de FPSO/FSU",
            "relaciona-se ao comportamento esperado em caso de dano ou inundação"
          ],
          "limites": [
            "o trecho não detalha critérios construtivos ou de teste de estanqueidade",
            "não aborda todas as exceções operacionais possíveis"
          ]
        },
        {
          "proposicao": "A fonte explica que, em tanques de carga parcialmente cheios, o sistema de gás inerte mantém o espaço livre acima do óleo cru em condição segura por meio da redução do teor de oxigênio para valor substancialmente abaixo do limite explosivo inferior da carga.",
          "trechos": [
            "E1d2dee61969ee6ad:1394:2093",
            "E1d2dee61969ee6ad:2093:2185"
          ],
          "condicoes": [
            "aplica-se a operações de carregamento e descarregamento em que os tanques ficam parcialmente cheios por boa parte do tempo",
            "refere-se a tanques de carga com óleo cru armazenado"
          ],
          "limites": [
            "o trecho não fornece estratégia detalhada de monitoramento, distribuição ou purga do gás inerte",
            "não deve ser interpretado como único controle de risco aplicável"
          ]
        }
      ]
    },
    {
      "id": "E726d47ce491bda6c",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte recomenda que o operador tenha procedimento para operações de tanques de carga que inclua perigos relevantes ao operador e identifique claramente as etapas críticas de segurança.",
          "trechos": [
            "E726d47ce491bda6c:0:690",
            "E726d47ce491bda6c:690:1383"
          ],
          "condicoes": [
            "aplica-se ao contexto de inspeção da gestão de operações de tanques de carga",
            "considera que procedimentos genéricos ou desatualizados são insuficientes"
          ],
          "limites": [
            "o trecho não define formato obrigatório do procedimento nem conteúdo mínimo completo",
            "documento de jurisdição estrangeira"
          ]
        },
        {
          "proposicao": "A fonte trata como preocupação evidente a ausência de avaliação de riscos para operações de tanques de carga, incluindo falhas em identificar perigos, riscos, controles e consequências.",
          "trechos": [
            "E726d47ce491bda6c:690:1383"
          ],
          "condicoes": [
            "aplica-se à gestão operacional de cargo tank operations",
            "refere-se tanto à inexistência de análise quanto à análise incompleta"
          ],
          "limites": [
            "não apresenta metodologia única de análise de riscos",
            "não quantifica níveis de risco ou critérios de aceitabilidade"
          ]
        },
        {
          "proposicao": "Para offloading, a fonte recomenda política ou procedimento de inspeção e teste de mangotes para assegurar a contenção, citando como mecanismos de perda de contenção impacto no convés, corrosão de liners, kink, choque de momento em paradas e outros mecanismos de envelhecimento.",
          "trechos": [
            "E726d47ce491bda6c:1383:2082",
            "E726d47ce491bda6c:2082:2219"
          ],
          "condicoes": [
            "aplica-se às operações de transferência para navio aliviador",
            "refere-se especificamente aos mangotes de offloading"
          ],
          "limites": [
            "o trecho não define frequência de inspeção, métodos de ensaio ou critérios de descarte",
            "não cobre todos os elementos do sistema de offloading além dos mangotes e shut-offs apropriados"
          ]
        }
      ]
    },
