      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte relata ocorrências de detecção inesperada de H2S em corrente de processo, tanques de carga e tanque de lastro, incluindo caso em que a investigação atribuiu a origem à atividade bacteriana e não aos poços.",
          "trechos": [
            "E3e4e6bfd1aff4d0d:0:700",
            "E3e4e6bfd1aff4d0d:700:1397"
          ],
          "condicoes": [
            "aplica-se aos eventos resumidos no alerta de segurança",
            "inclui instalações não originalmente classificadas como sour service"
          ],
          "limites": [
            "são exemplos de eventos e não estimativa de prevalência geral",
            "o trecho não relaciona diretamente o H2S a corrosão estrutural específica dos tanques"
          ]
        },
        {
          "proposicao": "No evento de entrada em tanque de lastro, após leitura inicial de 0 ppm, a agitação da camada de lodo fez o monitor alarmar com H2S elevado, levando à saída imediata do trabalhador e suspensão da atividade até elaboração de plano de entrada com mitigação para H2S.",
          "trechos": [
            "E3e4e6bfd1aff4d0d:700:1397"
          ],
          "condicoes": [
            "aplica-se ao cenário de limpeza e agitação de lodo em tanque de lastro",
            "depende da possibilidade de liberação de H2S retido em sedimentos"
          ],
          "limites": [
            "o caso é episódico e não prova que todo lodo em tanque de lastro gere H2S",
            "o trecho não descreve o plano de entrada adotado depois"
          ]
        },
        {
          "proposicao": "A fonte recomenda inspeções periódicas em tanques estagnados, avaliação de H2S no fundo antes de entrada com agitação de lodo, inclusão de procedimentos de mitigação e análises de risco robustas para ameaça de produção de H2S em vasos e tanques.",
          "trechos": [
            "E3e4e6bfd1aff4d0d:1397:2093",
            "E3e4e6bfd1aff4d0d:2093:2204"
          ],
          "condicoes": [
            "aplica-se a instalações offshore sujeitas a formação inesperada de H2S",
            "ganha relevância quando houver materiais estagnados, lodo ou potencial de souring"
          ],
          "limites": [
            "documento de recomendação estrangeiro",
            "o trecho não apresenta frequência de inspeção nem método analítico obrigatório"
          ]
        }
      ]
    }
